package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var inputLines []string
var currentLine int

func readline() string {
	line := inputLines[currentLine]
	currentLine++
	return line
}

func output(x string) {
	fmt.Println(x)
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		inputLines = append(inputLines, line)
	}

	nStr := readline()
	n, _ := strconv.Atoi(nStr)

	for test := 0; test < n; test++ {
		xStr := readline()
		x, _ := strconv.Atoi(xStr)

		arrStr := strings.Split(readline(), " ")
		arr := make([]int, len(arrStr))
		for i, s := range arrStr {
			val, _ := strconv.Atoi(s)
			arr[i] = val
		}

		result := "YES"

		first := arr[x-1]
		var second int
		if first != 0 {
			second = arr[first-1]
		} else {
			second = 0
		}

		if first == 0 {
			result = "NO"
		} else if second == 0 {
			result = "NO"
		}

		output(result)
	}
}
